import unittest,re
from tools.kjv_archive import load_register,read
class ThessaloniansTwoRestraintTests(unittest.TestCase):
 def test_restraint_and_brotherly_discipline(self):
  prior,_=load_register('0.10-kjv.253');lang,manifest=load_register('0.10-kjv.254')
  self.assertEqual(prior.lexicon,{k:lang.lexicon[k] for k in prior.lexicon})
  for attr in ('pairs','suffix','prefix','possessors','roman'):self.assertEqual(getattr(prior,attr),getattr(lang,attr))
  cases={c['id'].removeprefix('2-thessalonians-'):c for c in read(lang.folder/'thessalonians2-restraint-and-brotherly-discipline-cases.json')};self.assertEqual(len(cases),47)
  for c in cases.values():
   r=lang.compile(c['analysis']);self.assertEqual(c['expectedText'],r['text']);self.assertEqual(c['expectedGloss'],r['gloss']);self.assertNotIn('!',r['text'])
   self.assertFalse({'one','matter','worship'}&set(r['keys']))
  anchors={'1:1': ['kjv_paul_acts and kjv_silvanus_second_corinthians and kjv_timotheus_acts', 'god ourone/father'], '1:2': ['grace to you and peace', 'from god ourone/father'], '1:3': ['wesg to god always for you', 'your/faith exceed:adv grow:pr', 'each of you all towards each other'], '1:4': ['wesg ourselves', 'god kjv_church_assembly:pl', 'all your/persecute:ev:pl and kjv_afflict:ev:pl'], '1:5': ['god kjv_righteous judgment manifest token', 'god kingdom worthy reckon:psv:may', 'also suffer'], '1:6': ['with god kjv_righteous thing', 'kjv_afflict:ev to they who you kjv_afflict:pr recompense:inf'], '1:7': ['rest:ev with wesg', 'from heaven with his/mighty angel:pl'], '1:8': ['in flame:cv fire', 'god know:neg:pr', 'kjv_gospel obey:neg:pr', 'kjv_avenge:ev'], '1:9': ['eternal destroy:ev', 'from kjv_lord kjv_presence', 'from his/power glory'], '1:10': ['in his/saint:pl', 'all who believe:pr', 'ourone/testimony among you believe:psv:pa', 'that day'], '1:11': ['wesg always for you pray:pr', 'ourone/god', 'good pleasure of his/goodness', 'work of faith with power'], '1:12': ['name in you glorify:psv:may and you in he', 'according_to ourone/god'], '2:1': ['wesg you:a beseech:pr', 'ourone/gather:ev together to he'], '2:2': ['neither by spirit nor by word nor by letter as from wesg', 'kjv_christ_title day near'], '2:3': ['no person by any means', 'day come:neg:fu', 'first kjv_falling_away_thessalonians', 'man of sin', 'son of destroy:ev'], '2:4': ['who contrary stand:pr', 'himself above all', 'he as god in god kjv_temple sit:pr', 'himself that he god be:pr'], '2:5': ['you remember:neg:q', 'when i yet with you be:pa', 'i these thing:pl to you tell:pa'], '2:6': ['what restrain:pr', 'in his/time reveal:psv:may'], '2:7': ['mystery of kjv_iniquity already work:pr', 'he who now restrain:pr restrain:fu', 'until he out of way take:psv:pr'], '2:8': ['then that wicked person', 'his/mouth spirit kjv_consume:fu', 'his/come:ev bright:ev destroy:fu'], '2:9': ['according_to kjv_satan_temptation work:ev', 'all power and sign:pl and kjv_lie_false:cv wonder:pl'], '2:10': ['deceive:ev of kjv_unrighteousness', 'love of truth receive:neg:pa', 'save:psv:may'], '2:11': ['god to they strong kjv_delusion send:fu', 'kjv_lie_false:ev believe:opt'], '2:12': ['all condemn:psv:may', 'truth believe:neg:pa', 'kjv_unrighteousness pleasure have:pa'], '2:13': ['wesg always to god for you', 'from beginning', 'through spirit sanctify:ev and truth belief'], '2:14': ['by ourone/kjv_gospel call:pa', 'glory obtain:ev'], '2:15': ['kjv_firmly stand:imp', 'kjv_tradition:pl', 'by word or ourone/letter'], '2:16': ['ourone/kjv_lord kjv_jesus_matthew kjv_christ_title himself and god even ourone/father', 'wesg:a love:perf', 'eternal comfort:ev and good hope through grace'], '2:17': ['your/heart:pl comfort:opt', 'every good word and work kjv_establish:opt'], '3:1': ['for wesg pray:imp', 'kjv_lord word freely run:may', 'glorify:psv:may'], '3:2': ['wesg from kjv_unreasonable_thessalonians and wicked man:pl', 'not all man:pl faith have:pr'], '3:3': ['kjv_lord faithful', 'from evil keep:fu'], '3:4': ['wesg in kjv_lord', 'you thing:pl which wesg command:pr do:pr and do:fu'], '3:5': ['your/heart:pl', 'god love', 'patient wait:ev for kjv_christ_title'], '3:6': ['ourone/kjv_lord', 'every brother who kjv_unruly_thessalonians:adv walk:pr', 'which he from wesg receive:pa'], '3:7': ['wesg follow:inf should', 'wesg ourselves', 'kjv_unruly_thessalonians:adv behave:neg:pa'], '3:8': ['bread without price eat:pa', 'labour and kjv_toil night and day', 'any of you burden:neg:may'], '3:9': ['not because wesg authority have:neg:pr', 'ourselves to you example make:inf'], '3:10': ['when wesg with you be:pa', 'if any person work:inf will:neg:pr', 'neither he eat:opt'], '3:11': ['wesg hear:pr', 'work at all do:neg:cv', 'kjv_busybody_thessalonians:pl'], '3:12': ['wesg by ourone/kjv_lord', 'with quiet:ev they work:opt', 'their/own bread eat:opt'], '3:13': ['in good do:ev weary:neg:imp'], '3:14': ['ourone/word by this letter', 'that person notice:imp', 'company have:neg:imp', 'shame:psv:may'], '3:15': ['he as enemy reckon:neg:imp', 'as brother warning give:imp'], '3:16': ['kjv_lord of peace himself', 'peace always by all means', 'with you all'], '3:17': ['kjv_paul_acts greeting with my/own hand', 'in every letter token', 'so i write:pr'], '3:18': ['ourone/kjv_lord kjv_jesus_matthew kjv_christ_title grace with you all', 'amen']}
  for ref,parts in anchors.items():
   for part in parts:self.assertIn(part,cases[ref.replace(':','-')]['analysis'])
  self.assertIn('kjv_christ_title day near',cases['2-2']['analysis'])
  self.assertIn('he as god in god kjv_temple',cases['2-4']['analysis'])
  self.assertIn('what restrain:pr',cases['2-6']['analysis'])
  self.assertIn('he who now restrain:pr restrain:fu',cases['2-7']['analysis'])
  self.assertIn('god to they strong kjv_delusion send:fu',cases['2-11']['analysis'])
  self.assertIn('from beginning',cases['2-13']['analysis'])
  self.assertIn('not all man:pl faith have:pr',cases['3-2']['analysis'])
  self.assertIn('if any person work:inf will:neg:pr',cases['3-10']['analysis'])
  self.assertIn('he as enemy reckon:neg:imp',cases['3-15']['analysis'])
  self.assertIn('my/own hand',cases['3-17']['analysis'])
  self.assertEqual(len(set(lang.lexicon)-set(prior.lexicon)),3)
  self.assertEqual(manifest['baseForgeHead'],read(prior.folder/'manifest.json')['forgeHead'])
